sys_script_include.script:
var ServiceDeskIncidentHandler = Class.create();
ServiceDeskIncidentHandler.prototype = {
    initialize: function() {
    },

    /**
     * Creates a new servicedesk_incident record from parsed request body
     * @param {Object} data - parsed JSON body from the REST request
     * @returns {Object} result object with success flag and details
     */
    createIncident: function(data) {
        var result = {};
        var warnings = [];

		// Debugging log
		//gs.info('DEBUG - incoming data: ' + JSON.stringify(data));

        try {
            // 1. Requester is mandatory - no point continuing without it
            var requesterSysId = null;
            if (data.requester_email) {
                requesterSysId = this._findUserByEmail(data.requester_email);
            }

            if (!requesterSysId) {
                result.success = false;
                result.error = 'Requester not found for email: ' + data.requester_email;
                return result;
            }

            // 2. Optional fields - assignment group, assigned to, and configuration item.
            // If not found, we just leave them empty and proceed.
            var groupSysId = null;
            if (data.assignment_group) {
                groupSysId = this._findGroupByName(data.assignment_group);
            }

            var assignedToSysId = null;
            if (data.assigned_to_email) {
                assignedToSysId = this._findUserByEmail(data.assigned_to_email);
            }

            // CI is matched by serial number first (physically unique),
            // falling back to name only if that doesn't resolve.
            var ciSysId = null;
            if (data.ci_serial_number || data.ci_name) {
                ciSysId = this._findConfigurationItem(data.ci_serial_number, data.ci_name);
            }

            // 3. Create the record
            var gr = new GlideRecordSecure('x_1952794_servic_0_servicedesk_incident');
            gr.initialize();

            gr.short_description = data.short_description || '';
            gr.description = data.description || '';
            gr.servicedesk_category = data.category || '';
            gr.servicedesk_subcategory = data.subcategory || '';
            gr.external_servicedesk_number = data.external_number || '';
            gr.servicedesk_requester = requesterSysId;

            // Impact and Urgency arrive as text (LOW/MEDIUM/HIGH/CRITICAL)
            // from the Spring Boot backend and need to be converted to the
            // numeric ServiceNow choice values.
            if (data.impact && !this._isRecognizedLevel(data.impact)) {
                warnings.push('Unrecognized impact value: ' + data.impact + ', defaulted to Low');
            }
            gr.impact = this._convertImpactUrgencyToServiceNowValue(data.impact);

            if (data.urgency && !this._isRecognizedLevel(data.urgency)) {
                warnings.push('Unrecognized urgency value: ' + data.urgency + ', defaulted to Low');
            }
            gr.urgency = this._convertImpactUrgencyToServiceNowValue(data.urgency);

            if (groupSysId) {
                gr.assignment_group = groupSysId;
            }
            if (assignedToSysId) {
                gr.assigned_to = assignedToSysId;
            }
            if (ciSysId) {
                gr.cmdb_ci = ciSysId;
            }

            var newSysId = gr.insert();

            if (newSysId) {
                result.success = true;
                result.sys_id = newSysId;
                result.number = gr.getValue('number');

                // Let the caller know if optional lookups didn't resolve
                if (data.assignment_group && !groupSysId) {
                    warnings.push('Assignment group not found: ' + data.assignment_group);
                }
                if (data.assigned_to_email && !assignedToSysId) {
                    warnings.push('Assigned to user not found: ' + data.assigned_to_email);
                }
                if ((data.ci_serial_number || data.ci_name) && !ciSysId) {
                    warnings.push('Configuration item not found (serial: ' + data.ci_serial_number +
                        ', name: ' + data.ci_name + ')');
                }
                if (warnings.length > 0) {
                    result.warnings = warnings;
                }
            } else {
                result.success = false;
                result.error = 'Insert failed, check field values';
            }

        } catch (ex) {
            result.success = false;
            result.error = ex.getMessage ? ex.getMessage() : ex.toString();
        }

        return result;
    },

    _findUserByEmail: function(email) {
        var userGr = new GlideRecordSecure('sys_user');
        userGr.addQuery('email', email);
        userGr.query();
        if (userGr.next()) {
            return userGr.getUniqueValue();
        }
        return null;
    },

    _findGroupByName: function(name) {
        var groupGr = new GlideRecordSecure('sys_user_group');
        groupGr.addQuery('name', name);
        groupGr.query();
        if (groupGr.next()) {
            return groupGr.getUniqueValue();
        }
        return null;
    },

    /**
     * Finds a Configuration Item by serial number first (physically unique),
     * falling back to name if the serial number is missing or no match is
     * found. Queries the base cmdb_ci table, which reaches records from any
     * child CI class since extended tables share the same sys_id and base
     * fields with their parent.
     *
     * @param {String} serialNumber - optional, preferred match key
     * @param {String} name - optional, fallback match key
     * @returns {String|null} sys_id of the matched CI, or null if not found
     */
    _findConfigurationItem: function(serialNumber, name) {
        if (serialNumber) {
            var ciBySerialGr = new GlideRecordSecure('cmdb_ci');
            ciBySerialGr.addQuery('serial_number', serialNumber);
            ciBySerialGr.query();
            if (ciBySerialGr.next()) {
                return ciBySerialGr.getUniqueValue();
            }
        }

        if (name) {
            var ciByNameGr = new GlideRecordSecure('cmdb_ci');
            ciByNameGr.addQuery('name', name);
            ciByNameGr.query();
            if (ciByNameGr.next()) {
                return ciByNameGr.getUniqueValue();
            }
        }

        return null;
    },

    /**
     * Converts a text-based impact/urgency level (as sent by the Spring Boot
     * backend) into the corresponding ServiceNow numeric choice value.
     * Impact and Urgency share the same 4-level scale, so one function
     * covers both fields.
     *
     * Falls back to '4' (Low) if the value is missing or unrecognized,
     * rather than blocking incident creation over a non-critical field.
     *
     * @param {String} textValue - e.g. "CRITICAL", "HIGH", "MEDIUM", "LOW"
     * @returns {String} the ServiceNow numeric value as a string
     */
    _convertImpactUrgencyToServiceNowValue: function(textValue) {
        var mapping = {
            'CRITICAL': '1',
            'HIGH': '2',
            'MEDIUM': '3',
            'LOW': '4'
        };

        var DEFAULT_VALUE = '4';

        if (!textValue) {
            return DEFAULT_VALUE;
        }

        return mapping[textValue.toUpperCase()] || DEFAULT_VALUE;
    },

    _isRecognizedLevel: function(textValue) {
        var validValues = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW'];
        return validValues.indexOf(textValue.toUpperCase()) !== -1;
    },

    type: 'ServiceDeskIncidentHandler'
};
